return $input.all().map(item => {
  const j = item.json;
  const fields = j.fields || j;
  return { json: { job_record_id: j.id || null, ...fields } };
});

const job = $json;
const history = $('Get_Application_History').all().map(i => ({ company: i.json.fields?.company, title: i.json.fields?.title }));

const candidateProfile = {
  domain: 'Cybersécurité',
  priority_technologies: ['Microsoft Sentinel','Microsoft Defender XDR','Microsoft Defender for Endpoint','Microsoft Defender for Cloud','Microsoft Defender Vulnerability Management','Microsoft Entra ID','Microsoft Intune','Microsoft Azure','Microsoft Purview','KQL','Logic Apps','SOAR','Tenable'],
  secondary_technologies: ['CrowdStrike','Palo Alto','AWS Security','QRadar','SIEM','EDR','XDR','IAM','PAM','CSPM','Vulnerability Management'],
  seniority_target: ['Senior','Architecte'],
  languages: { french: 'native', english: 'professional_intermediate' },
  home_city: $vars.HOME_CITY || 'Quebec City',
  home_province: $vars.HOME_PROVINCE || 'Quebec',
  accepts_occasional_travel_per_year: parseInt($vars.MAX_OCCASIONAL_TRIPS_PER_YEAR || '4', 10)
};

const masterCvSummary = {
  note: 'REMPLACER par un export structuré réel du CV maître FR/EN (compétences, expériences, certifications, projets).',
  source: 'master_cv_fr / master_cv_en'
};

const systemPrompt = `Tu es JOB_ANALYZER, un agent d'analyse d'offres d'emploi en cybersécurité dans un pipeline n8n automatisé. Réponds EXCLUSIVEMENT via l'outil return_job_analysis, jamais en texte libre.
Technologies prioritaires: ${candidateProfile.priority_technologies.join(', ')}.
Technologies secondaires (jamais éliminatoires seules): ${candidateProfile.secondary_technologies.join(', ')}.
Ne rejette jamais une offre uniquement parce qu'elle demande 1-2 technologies différentes.
Utilise une recherche sémantique de titres FR/EN (Analyste SOC, Security Analyst, Threat Hunter, Security Engineer/Architect, etc.), découvre aussi des variantes plausibles (discovered_title_variants).
Priorité séniorité: Senior, Architecte; un poste intermédiaire reste valorisable si rémunération/portée/évolution le justifient.
Règles de localisation strictes: Ville de Québec = onsite/hybride/remote OK; reste du Québec = priorité remote (présence occasionnelle OK); Montréal = remote + présence occasionnelle (~1x/mois) OK; reste du Canada = remote uniquement; USA = accepter SEULEMENT si Canada/remote Canada explicitement mentionné, ne jamais le supposer. Déplacements occasionnels 2-4/an acceptables.
Emploi: priorité permanent temps plein, accepter aussi temps partiel soir.
Cote de sécurité: exclure si obligatoire et non détenue/non obtenable; 'eligible to obtain' n'est pas bloquant.
Langues: bilingue FR/EN, anglais professionnel INTERMÉDIAIRE seulement - ne jamais exagérer.
Salaire absent ne doit jamais pénaliser le score (salary_match neutre).
blocking_reasons possibles: location_incompatible, onsite_required_outside_quebec, canada_not_accepted, clearance_required, not_cybersecurity, student_internship, salary_below_threshold, already_applied, expired.
Pondérations overall_score: technique 30%, expérience 20%, technologies 15%, séniorité 10%, localisation 10%, ATS 10%, langues 5%.
Classification: 80-100 PRIORITY, 70-79 APPLY, 60-69 MANUAL_REVIEW, 0-59 REJECT. Un blocking_reason force REJECT ou MANUAL_REVIEW même si score élevé.
interview_probability: score 0-100 + label LOW/MEDIUM/HIGH/VERY_HIGH, jamais présenté comme certitude statistique.
Anti-hallucination: n'affirme jamais une compétence/certification absente du CV maître fourni; marque les déductions comme INFERRED dans notes, jamais comme fait acquis.
reason: 1-3 phrases concises et auditables.`;

const userMessage = JSON.stringify({
  job_offer: job,
  candidate_profile: candidateProfile,
  master_cv_summary: masterCvSummary,
  application_history: history
});

return [{ json: { ...job, system_prompt: systemPrompt, user_message: userMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const toolUse = (body.content || []).find(c => c.type === 'tool_use');
  const analysis = toolUse ? toolUse.input : {};
  const job = $('Build_Job_Analyzer_Request').first().json;
  return { json: { ...job, claude_analysis: { ...analysis, model: body.model } } };
});

const j = $json;
const reviewSystemPrompt = `Tu es un REVIEWER OpenAI dans un pipeline de recherche d'emploi cybersécurité. Tu reçois une offre d'emploi et l'évaluation de Claude (JOB_ANALYZER). Cherche activement: erreur de scoring, compétence prétendument possédée mais absente du CV, mauvaise interprétation, critère obligatoire manquant, problème de localisation, hallucination. Réponds UNIQUEMENT en JSON: {\"overall_score\": number, \"issues_found\": string[], \"corrected_blocking_reasons\": string[], \"agrees_with_claude\": boolean, \"reason\": string}.`;
const reviewUserMessage = JSON.stringify({ job_offer: { title: j.title, company: j.company, description: j.description, location: j.location, work_mode: j.work_mode }, claude_analysis: j.claude_analysis });
return [{ json: { ...j, review_system_prompt: reviewSystemPrompt, review_user_message: reviewUserMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const job = $('Build_OpenAI_Reviewer_Request').first().json;
  let review = {};
  try { review = JSON.parse(body.choices[0].message.content); } catch (e) { review = { overall_score: job.claude_analysis.overall_score, issues_found: ['parse_error'], agrees_with_claude: true, reason: 'Fallback: réponse OpenAI non parsable' }; }
  const divergence = Math.abs((review.overall_score ?? job.claude_analysis.overall_score) - job.claude_analysis.overall_score);
  return { json: { ...job, openai_review: review, score_divergence: divergence } };
});

const j = $json;
const secondSystemPrompt = j.system_prompt + '\n\nATTENTION: Une 2e analyse est demandée car un reviewer OpenAI diverge de plus de 10 points de ta première évaluation. Reconsidère ton scoring à la lumière de ses observations, sans supposer que le reviewer a automatiquement raison.';
const secondUserMessage = JSON.stringify({ original_analysis: j.claude_analysis, openai_review: j.openai_review, job_offer: { title: j.title, company: j.company, description: j.description, location: j.location, work_mode: j.work_mode } });
return [{ json: { ...j, second_system_prompt: secondSystemPrompt, second_user_message: secondUserMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const toolUse = (body.content || []).find(c => c.type === 'tool_use');
  const analysis = toolUse ? toolUse.input : {};
  const job = $('Build_Claude_Second_Analysis_Request').first().json;
  return { json: { ...job, final_analysis: { ...analysis, model: body.model }, second_opinion_used: true } };
});
